static void show_error(const char *text){GtkAlertDialog *dialog=gtk_alert_dialog_new("%s",text);gtk_alert_dialog_show(dialog,ui.window);g_object_unref(dialog);}
static void error_take(GError *error){if(error){show_error(error->message);g_error_free(error);}}
static GtkWidget *box(GtkOrientation orientation,int spacing){return gtk_box_new(orientation,spacing);}
static GtkWidget *label(const char *text){GtkWidget *widget=gtk_label_new(text);gtk_label_set_xalign(GTK_LABEL(widget),0);gtk_label_set_wrap(GTK_LABEL(widget),TRUE);return widget;}
