static GtkWidget *entry(const char *placeholder){GtkWidget *widget=gtk_entry_new();gtk_entry_set_placeholder_text(GTK_ENTRY(widget),placeholder);return widget;}
static GtkWindow *window(const char *title,int width,int height,gboolean modal){GtkWindow *result=GTK_WINDOW(gtk_window_new());gtk_window_set_application(result,ui.application);gtk_window_set_title(result,title);gtk_window_set_default_size(result,width,height);gtk_window_set_transient_for(result,ui.window);gtk_window_set_modal(result,modal);gtk_widget_add_css_class(GTK_WIDGET(result),"bitskim-window");return result;}
