static void refresh_clicked(GtkButton *button_,gpointer data){(void)button_;(void)data;bs_refresh(ui.client.engine);}
static void queue_action(GtkButton *button_,gpointer action_){(void)button_;int action=GPOINTER_TO_INT(action_);if(action==0)bs_cancel(ui.client.engine);else if(action==1)bs_queue_pause(ui.client.engine);else if(action==2)bs_queue_continue(ui.client.engine);else if(action==3){if(bs_status(ui.client.engine)->active)show_error("Wait for the active file to finish before skipping it.");else bs_queue_skip(ui.client.engine);}else bs_queue_clear(ui.client.engine);}

/* Virtual model: only visible manifest entries are read from the disk-backed list. */
