    ui.offer_code=label("");char code[20],*verification=NULL;if(bs_pairing_code(ui.client.engine,code))verification=g_strdup_printf("Verify on both screens: %s%s",code,bs_trust_status(ui.client.engine)==1?" · Saved identity matches":"");gtk_label_set_text(GTK_LABEL(ui.offer_code),verification?verification:"Computer names are not verified.");g_free(verification);gtk_box_append(GTK_BOX(content),ui.offer_code);
