static void qr_draw(GtkDrawingArea *area,cairo_t *cr,int width,int height,gpointer data){(void)area;(void)data;cairo_set_source_rgb(cr,1,1,1);cairo_paint(cr);if(ui.qr_expires<=time(NULL))return;int size=qrcodegen_getSize(ui.qr),scale=MIN(width,height)/(size+8);if(scale<1)return;int left=(width-(size+8)*scale)/2,top=(height-(size+8)*scale)/2;cairo_set_source_rgb(cr,0,0,0);for(int y=0;y<size;y++)for(int x=0;x<size;x++)if(qrcodegen_getModule(ui.qr,x,y))cairo_rectangle(cr,left+(x+4)*scale,top+(y+4)*scale,scale,scale);cairo_fill(cr);}
static void qr_generate(GtkButton *button_,gpointer data){(void)button_;(void)data;GtkStringObject *selected=GTK_STRING_OBJECT(gtk_drop_down_get_selected_item(GTK_DROP_DOWN(ui.qr_addresses)));char uri[256];unsigned char temp[qrcodegen_BUFFER_LEN_MAX];if(!selected||!bs_invitation_create(ui.client.engine,gtk_string_object_get_string(selected),uri,sizeof uri)){show_error("Enable receiving and certificate encryption, and choose a reachable LAN address.");return;}if(!qrcodegen_encodeText(uri,temp,ui.qr,qrcodegen_Ecc_MEDIUM,1,20,qrcodegen_Mask_AUTO,TRUE)){show_error("Cannot render the invitation QR.");return;}ui.qr_expires=time(NULL)+300;gtk_widget_queue_draw(ui.qr_canvas);}
static void qr_open(GtkButton *button_,gpointer data){(void)button_;(void)data;if(ui.qr_window){gtk_window_present(ui.qr_window);return;}GtkWindow *dialog=window("Connection QR — BitSkim",420,510,FALSE);watch_child(dialog,&ui.qr_window);GtkWidget *content=box(GTK_ORIENTATION_VERTICAL,14);margins(content,20);gtk_window_set_child(dialog,content);GtkStringList *addresses=gtk_string_list_new(NULL);struct ifaddrs *first=NULL;if(!getifaddrs(&first)){for(struct ifaddrs *p=first;p;p=p->ifa_next)if(p->ifa_addr&&p->ifa_addr->sa_family==AF_INET&&(p->ifa_flags&IFF_UP)&&!(p->ifa_flags&IFF_LOOPBACK)){char address[INET_ADDRSTRLEN];if(inet_ntop(AF_INET,&((struct sockaddr_in *)p->ifa_addr)->sin_addr,address,sizeof address))gtk_string_list_append(addresses,address);}freeifaddrs(first);}ui.qr_addresses=gtk_drop_down_new(G_LIST_MODEL(addresses),NULL);gtk_box_append(GTK_BOX(content),label("Address reachable from the sending phone"));gtk_box_append(GTK_BOX(content),ui.qr_addresses);gtk_box_append(GTK_BOX(content),button("_Generate invitation",G_CALLBACK(qr_generate),NULL));ui.qr_caption=label("Invitations expire after five minutes. Incoming files still require approval.");gtk_box_append(GTK_BOX(content),ui.qr_caption);ui.qr_canvas=gtk_drawing_area_new();gtk_widget_set_size_request(ui.qr_canvas,330,330);gtk_drawing_area_set_draw_func(GTK_DRAWING_AREA(ui.qr_canvas),qr_draw,NULL,NULL);gtk_box_append(GTK_BOX(content),ui.qr_canvas);gtk_box_append(GTK_BOX(content),button("Close",G_CALLBACK(close_clicked),dialog));ui.qr_expires=0;gtk_window_present(dialog);}
