static void notifications_tick(void){
    if(!ui.client.notifications){if(ui.alerts.pending)alerts_clear(&ui.alerts);return;}
    if(!alerts_ready(&ui.alerts,ui.client.engine))return;
    GNotification *notice=alerts_notification(&ui.alerts);g_free(ui.notification_folder);ui.notification_folder=g_strdup(ui.alerts.folder);ui.notification_serial=ui.alerts.seen;
    g_application_send_notification(G_APPLICATION(ui.application),"transfer-result",notice);g_object_unref(notice);alerts_clear(&ui.alerts);
}
static gboolean tick(gpointer data){(void)data;bs_service(ui.client.engine,4);retained_refresh();BSStatus visual=*bs_status(ui.client.engine);BSRecoveryProgress recovery;if(bs_recovery_progress(ui.client.engine,&recovery)&&recovery.phase==2){visual.transferred=recovery.checked_bytes;visual.total=recovery.check_total;}const BSStatus *status=&visual;refresh_peers();incoming();notifications_tick();
    char *message=linux_display(bs_user_status(ui.client.engine));char *next=strstr(message," Next: ");if(next)*next='\n';if(g_strcmp0(message,ui.status_key)){gtk_label_set_text(GTK_LABEL(ui.status),message);gtk_widget_set_tooltip_text(ui.status,message);g_free(ui.status_key);ui.status_key=g_strdup(message);}g_free(message);
    char progress[512];bs_progress_summary(ui.client.engine,progress,sizeof progress);gtk_label_set_text(GTK_LABEL(ui.details),progress);gtk_progress_bar_set_fraction(GTK_PROGRESS_BAR(ui.progress),status->total?(double)MIN(status->transferred,status->total)/(double)status->total:0);
    int count=bs_queue_count(ui.client.engine);char *queue=g_strdup_printf("%d outgoing entries%s%s",count,bs_queue_paused(ui.client.engine)?" · paused":"",bs_state_restored(ui.client.engine)?" · restored; Continue to send":"");gtk_label_set_text(GTK_LABEL(ui.queue_label),queue);g_free(queue);gboolean idle=!status->active&&!count&&!bs_queue_scanning(ui.client.engine);gtk_widget_set_sensitive(ui.pick,idle);gtk_widget_set_sensitive(ui.pick_folder,idle);gtk_widget_set_sensitive(ui.send,idle&&ui.files->len>0);gtk_widget_set_sensitive(ui.cancel,status->active||count);
    if(ui.tools){char code[20];char *caption=bs_pairing_code(ui.client.engine,code)?g_strdup_printf("Verify: %s%s",code,bs_trust_status(ui.client.engine)==1?" · Saved identity matches":""):g_strdup("Pair during an encrypted connection. QR invitations verify the receiving identity.");gtk_label_set_text(GTK_LABEL(ui.tools_code),caption);g_free(caption);}
    if(ui.qr_window&&ui.qr_expires){long seconds=(long)(ui.qr_expires-time(NULL));char *caption=seconds>0?g_strdup_printf("Expires in %ld seconds. Incoming files still require approval.",seconds):g_strdup("Invitation expired. Generate a new code.");gtk_label_set_text(GTK_LABEL(ui.qr_caption),caption);g_free(caption);if(seconds<=0){ui.qr_expires=0;gtk_widget_queue_draw(ui.qr_canvas);}}
    return G_SOURCE_CONTINUE;
}
